{
  "findings": [
    {
      "check_id": "CKV_AWS_53",
      "title": "S3 bucket does not block public ACLs",
      "resource": "aws_s3_bucket_public_access_block.document_storage",
      "severity": "HIGH",
      "explanation": "The public access block omits block_public_acls, which defaults to false and allows new public ACLs to be applied to the referenced S3 bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"document_storage\" {\n  bucket                  = aws_s3_bucket.document_storage.id\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n",
  "fix_summary": "Enabled block_public_acls so the S3 bucket rejects new public ACLs. Existing public access protections were preserved."
}
